import XCTest

final class BookClubTests: XCTestCase {
    func testOpenBookClubAndReadMessages() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        let row = app.staticTexts["Book Club"]
        XCTAssertTrue(row.waitForExistence(timeout: 15), "Book Club row not found")
        row.tap()

        sleep(4)

        let labels = app.staticTexts.allElementsBoundByIndex.map { $0.label }
        print("BOOKCLUB_LABELS_BEGIN")
        for l in labels where !l.isEmpty { print("LABEL: " + l) }
        print("BOOKCLUB_LABELS_END")

        let shot = XCUIScreen.main.screenshot()
        let attachment = XCTAttachment(screenshot: shot)
        attachment.lifetime = .keepAlways
        add(attachment)
    }
}

